  @override
  String get salStubReceiveLightning =>
      'Στο Kute, πάτησε Λήψη και διάλεξε το πορτοφόλι εξόδων. Μπορείς να μοιραστείς τη διεύθυνση Lightning ή τον κωδικό QR του. Για να ζητήσεις συγκεκριμένο ποσό, άνοιξε «Περισσότερες επιλογές», διάλεξε «Αίτημα συγκεκριμένου ποσού», βάλε το ποσό και πάτησε «Δημιουργία αιτήματος». Μοιράσου το αίτημα ή τον κωδικό QR με τον αποστολέα. Ένας κανονικός λογαριασμός Bitcoin, υλικού ή μόνο παρακολούθησης λαμβάνει on-chain. Διάλεξε το πορτοφόλι εξόδων για λήψη μέσω Lightning.';

  @override
