  @override
  String get salStubSendBuy =>
      'Στο Kute, πάτησε Λήψη για να πάρεις Bitcoin από άλλο πορτοφόλι. Για αγορά, πάτησε Αγορά στην Αρχική και ακολούθησε τη διαδικασία αγοράς μέσω Cash App. Για αποστολή, πάτησε Αποστολή, διάλεξε τον λογαριασμό προέλευσης, βάλε το ποσό και σάρωσε ή επικόλλησε τον παραλήπτη στο «Αποστολή σε». Έλεγξε τον προορισμό και τη χρέωση και επιβεβαίωσε την πληρωμή. Οι κανονικοί λογαριασμοί Bitcoin στέλνουν on-chain. Το πορτοφόλι εξόδων υποστηρίζει και Lightning. Το άνοιγμα θέσης Επενδύσεων σε bitcoin δεν βάζει Bitcoin σε πορτοφόλι.';

  @override
  String get salStubWallets =>
      'Το Kute έχει πορτοφόλι εξόδων για Bitcoin και Lightning. Στην Προσθήκη πορτοφολιού, το «Πορτοφόλι Bitcoin» δημιουργεί ξεχωριστό λογαριασμό on-chain με νέα φράση ανάκτησης 12 λέξεων ή ανακτά μια υπάρχουσα φράση. Το αντίγραφό του εμφανίζεται ξεχωριστά στις Φράσεις ανάκτησης. Οι λογαριασμοί μόνο παρακολούθησης παρακολουθούν Bitcoin χωρίς να αποθηκεύουν κλειδιά υπογραφής. Κράτα όλες τις λέξεις ανάκτησης ιδιωτικές και βάλε τες μόνο στην οθόνη ανάκτησης πορτοφολιού, ποτέ στον Sal.';

  @override
